bool humanRestingTimestepSensitivityEnabledForApp() {
#ifdef NUMI_HUMAN_RESTING_SCENE
    return numi::matter::humanRestingTimestepSensitivityEnabled();
#else
    return false;
#endif
}

bool humanRestingOpticNerveFEMEnabledForApp() {
    const char* value=std::getenv("NUMI_HUMAN_RESTING_OPTIC_NERVE_FEM");
    if(value==nullptr||std::strcmp(value,"0")==0)return false;
    if(std::strcmp(value,"1")==0)return true;
    throw std::runtime_error("NUMI_HUMAN_RESTING_OPTIC_NERVE_FEM must be unset, 0, or 1");
}

// Wall-clock diagnostics only; never alter simulation time or state.
void reportHumanExecutionStage(const char* stage, std::uint32_t step = 0u) {
    static const bool enabled = [] {
        const char* value = std::getenv("NUMI_HUMAN_EXECUTION_STAGES");
        return value != nullptr && std::strcmp(value, "1") == 0;
    }();
    if (!enabled) {
        return;
    }
    static const auto origin = std::chrono::steady_clock::now();
    const double elapsed = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - origin).count();
    std::cout << "human_execution_stage=" << stage
              << " wall_elapsed_ms=" << elapsed
              << " stage_step=" << step << std::endl;
}

std::filesystem::path humanBrainMetallibPath() {
    NSString* executable = [[NSBundle mainBundle] executablePath];
    if (executable != nil) {
        // Frozen native cohorts colocate the operator/Brain library with the
        // executable and dylib; never fall through to a mutable build shader.
        const std::filesystem::path cohort =
            std::filesystem::path(executable.UTF8String).parent_path() /
            "metalrobo/MetalRobo.metallib";
        std::error_code cohortError;
        if (std::filesystem::is_regular_file(cohort, cohortError) && !cohortError)
            return cohort;
        const std::filesystem::path packaged =
            std::filesystem::path(executable.UTF8String).parent_path().parent_path() /
            "shaders/MetalRobo.metallib";
        std::error_code error;
        if (std::filesystem::is_regular_file(packaged, error) && !error) {
            return packaged;
        }
    }
    const std::filesystem::path configured{METALROBO_METALLIB};
    std::error_code error;
    if (std::filesystem::is_regular_file(configured, error) && !error) {
        return configured;
    }
    throw std::runtime_error(
        "Human Brain requires MetalRobo.metallib beside the executable's build bundle");
}

