    double sourceSupportForceParityMaximumNewtons = 0.0;
    std::uint32_t sourceSupportForceParityMaximumDof = MR_INVALID_INDEX;
    std::string muscleMetalDeviceName;
    bool persistentMetalHorizon = false;
