    bool persistentMtpPassiveStiffnessConfigured = false;
    bool persistentMtpPassiveStiffnessActive = false;
    double persistentMtpPassiveStiffnessNmPerRad = 0.0;
    std::uint32_t persistentPassiveCoordinateCouplingCount = 0u;
    double persistentPassiveCoordinateForceMaximumNewtons = 0.0;
    bool selectedTendonControl = false;
    bool selectedControlBaselineEvaluated = false;
    double selectedControlBaselineMaximumQDelta = 0.0;
    double selectedControlBaselineMaximumVDelta = 0.0;
    std::uint32_t selectedControlBaselineMaximumQDeltaIndex = MR_INVALID_INDEX;
    std::uint32_t selectedControlBaselineMaximumVDeltaIndex = MR_INVALID_INDEX;
    double selectedControlBaselineElapsedMilliseconds = 0.0;
    bool rootAssistanceEnabled = false;
    bool assistanceRemovalEvaluated = false;
    bool sourceConstraintPreloadApplied = false;
    double sourceConstraintPreloadMaximumNewtons = 0.0;
    std::uint32_t persistentCompletedSteps = 0u;
    // Compatibility metric: maximum pre-projection total delta-v / dt. Keep
    // smooth force acceleration and constraint/projection increments separate.
    double persistentMaximumAcceleration = 0.0;
    double persistentMaximumFreeAcceleration = 0.0;
    std::uint32_t persistentMaximumFreeAccelerationDof = MR_INVALID_INDEX;
    double persistentMaximumConstraintVelocityDelta = 0.0;
    std::uint32_t persistentMaximumConstraintVelocityDeltaDof = MR_INVALID_INDEX;
    double persistentMaximumPreProjectionVelocityDelta = 0.0;
    std::uint32_t persistentMaximumPreProjectionVelocityDeltaDof = MR_INVALID_INDEX;
    double persistentMaximumPublishedVelocityDelta = 0.0;
    std::uint32_t persistentMaximumPublishedVelocityDeltaDof = MR_INVALID_INDEX;
    double persistentMaximumPenetrationMeters = 0.0;
    double persistentNormalImpulse = 0.0;
    double persistentSourceLimitAbsoluteImpulse = 0.0;
    std::array<double, 4u> persistentConstraintImpulseWorkJoules{};
    std::array<double, 4u>
        persistentConstraintAbsoluteImpulseWorkJoules{};
    std::string persistentStandStatusNonCumulativeHex;
    double persistentRootAssistanceForce = 0.0;
    double persistentRootAssistanceTorque = 0.0;
    std::uint32_t compiledActiveMuscleCount = 0u;
    double compiledActivationResidualRms = 0.0;
    double compiledInitialActivationResidualRms = 0.0;
    double compiledMaximumAccelerationResidual = 0.0;
    double compiledMaximumVelocityIncrement = 0.0;
    bool compiledBalanced = false;
