                    const MRCompensatedRootTranslationGPU&,
                    const metalrobo::MetalArticulatedOperatorResult&,
                    const MetalMujocoVisualQueries&
                )> observer =
                    [&](std::uint32_t step,
                        std::span<const float> qBefore,
                        std::span<const float> vBefore,
                        const MRCompensatedRootTranslationGPU& rootBefore,
                        const metalrobo::MetalArticulatedOperatorResult& result,
                        const MetalMujocoVisualQueries& queries) {
                        if (restingSupportedPreludeSteps != 0u &&
                            step <= restingSupportedPreludeSteps)
                            return;
                        const std::uint32_t measuredTerminalStep =
                            *muscleStepCount + restingSupportedPreludeSteps;
                        const std::uint32_t measuredStep =
                            step - restingSupportedPreludeSteps;
                        require(queries.supportContacts.size() ==
                                    queries.supportSourceRecordIndices.size(),
                                "accepted observer lost runtime support-query lineage");
                        if (!observerSupportQueryCountObserved) {
                            retainedObserverSupportQueryCount =
                                queries.supportContacts.size();
                            observerSupportQueryCountObserved = true;
                        } else {
                            require(retainedObserverSupportQueryCount ==
                                        queries.supportContacts.size(),
                                    "runtime support-query count changed across accepted observer callbacks");
                        }
                        const auto observerProfileStart = trainingProfile
                            ? std::chrono::steady_clock::now()
                            : std::chrono::steady_clock::time_point{};
                        if (trainingProfile) ++restingObserverProfile.callbacks;
                        const auto& p=*static_cast<const NMHumanRespirationState*>(coupled.physiology.respiration->accepted.contents);
                        require(p.status.x==step&&!p.status.w,"body/respiratory accepted clocks differ");
                        const auto& b=result.standStatuses.front();
                        if (!restingHipCapsuleTerms.empty()) {
                            const auto& articulation=rigid.model.articulations.front();
                            require(result.standQ.size()==articulation.nq,
                                    "hip-capsule highwater lacks the accepted q state");
                            std::array<double,128u> generalizedTorque{};
                            const auto rightFlexionQ = rigid.model.dofs[
                                articulation.vOffset + 100u].qIndex - articulation.qOffset;
                            const auto leftFlexionQ = rigid.model.dofs[
                                articulation.vOffset + 114u].qIndex - articulation.qOffset;
                            const double rightFlexion = result.standQ[rightFlexionQ];
                            const double leftFlexion = result.standQ[leftFlexionQ];
                            require(std::isfinite(rightFlexion) &&
                                        std::isfinite(leftFlexion),
                                    "hip-capsule highwater received nonfinite accepted flexion");
                            hipCapsuleHighwater.rightFlexionMinRad = std::min(
                                hipCapsuleHighwater.rightFlexionMinRad, rightFlexion);
                            hipCapsuleHighwater.rightFlexionMaxRad = std::max(
                                hipCapsuleHighwater.rightFlexionMaxRad, rightFlexion);
                            hipCapsuleHighwater.leftFlexionMinRad = std::min(
                                hipCapsuleHighwater.leftFlexionMinRad, leftFlexion);
                            hipCapsuleHighwater.leftFlexionMaxRad = std::max(
                                hipCapsuleHighwater.leftFlexionMaxRad, leftFlexion);
                            constexpr double fitMinimumFlexionRad = -12.0 *
                                std::numbers::pi / 180.0;
                            if (rightFlexion < fitMinimumFlexionRad || rightFlexion > 0.0 ||
                                leftFlexion < fitMinimumFlexionRad || leftFlexion > 0.0)
                                ++hipCapsuleHighwater.samplesOutsideFlexionFitInterval;
                            double statePotential=0.0;
                            for (const auto& term : restingHipCapsuleTerms) {
                                const auto q0=rigid.model.dofs[
                                    articulation.vOffset+term.dofIndex0].qIndex-
                                    articulation.qOffset;
                                const auto q1=rigid.model.dofs[
                                    articulation.vOffset+term.dofIndex1].qIndex-
                                    articulation.qOffset;
                                const double gap=double(term.coordinate0)*result.standQ[q0]+
                                    double(term.coordinate1)*result.standQ[q1]-
                                    double(term.threshold);
                                const double positive=std::max(0.0,gap);
                                hipCapsuleHighwater.maxPositiveBranchGapRad=
                                    std::max(hipCapsuleHighwater.maxPositiveBranchGapRad,positive);
                                const double square=positive*positive;
                                const double magnitude=double(term.toeQuadratic)*square+
                                    double(term.toeCubic)*square*positive;
                                statePotential+=double(term.toeQuadratic)*square*positive/3.0+
                                    double(term.toeCubic)*square*square/4.0;
                                generalizedTorque[term.dofIndex0]-=
                                    double(term.coordinate0)*magnitude;
                                generalizedTorque[term.dofIndex1]-=
                                    double(term.coordinate1)*magnitude;
                            }
                            if (hipCapsuleBase5NmGapRad>0.0)
                                hipCapsuleHighwater.maxPositiveBranchGapOverBase5NmGap=
                                    std::max(hipCapsuleHighwater.maxPositiveBranchGapOverBase5NmGap,
                                        hipCapsuleHighwater.maxPositiveBranchGapRad/
                                            hipCapsuleBase5NmGapRad);
                            hipCapsuleHighwater.maxHipTorqueNormNm=std::max(
                                hipCapsuleHighwater.maxHipTorqueNormNm,
                                std::hypot(generalizedTorque[100],generalizedTorque[102]));
                            hipCapsuleHighwater.maxHipTorqueNormNm=std::max(
                                hipCapsuleHighwater.maxHipTorqueNormNm,
                                std::hypot(generalizedTorque[114],generalizedTorque[116]));
                            hipCapsuleHighwater.maxPotentialEnergyJ=std::max(
                                hipCapsuleHighwater.maxPotentialEnergyJ,statePotential);
                            ++hipCapsuleHighwater.acceptedStates;
                        }
                        if(terminalGeometryRequested&&step==measuredTerminalStep) {
                            require(result.standStatuses.size()==1u&&
                                    result.standQ.size()==rigid.model.articulations.front().nq&&
                                    result.standRootTranslations.size()==1u&&
                                    b.code==MR_NUMI_HUMAN_STAND_SUCCESS&&
                                    b.completedSteps==measuredTerminalStep&&
                                    mrCompensatedTranslationValid(result.standRootTranslations.front()),
                                    "terminal accepted-state capture lacks exact-N q/root/status");
                            terminalAcceptedQ=result.standQ;
                            terminalAcceptedRoot=result.standRootTranslations.front();
                            terminalAcceptedStandStatus=b;
                            terminalAcceptedSnapshotObserved=true;
                        }
                        const bool qIntegrationAuditSample =
                            qIntegrationWindow.contains(step);
                        const bool normalObserverSample =
                            !qIntegrationWindow.bounded ||
                            measuredStep % restingComMomentumAuditSegmentSteps == 0u ||
                            step == measuredTerminalStep;
                        const bool comMomentumObserverSample =
                            numiHumanAcceptedQAuditWindow::shouldSampleComMomentum(
                                qIntegrationWindow,
                                restingComMomentumAuditSegmentSteps,
                                step,
                                measuredTerminalStep);
                        if (normalObserverSample) {
                            const auto respirationTraceProfileStart = trainingProfile
                                ? std::chrono::steady_clock::now()
                                : std::chrono::steady_clock::time_point{};
                            numi::human::writeRespirationTraceSample(trace,p,coupled.physiology.respiration->parameters);
                            trace<<','<<step<<','
                                 <<b.contactAndAcceleration.x<<','<<b.contactAndAcceleration.y<<','<<b.contactAndAcceleration.z<<','
                                 <<b.factorAndAssistance.z<<','<<b.factorAndAssistance.w<<','<<p.control.x<<','<<p.control.y<<','
                                 <<p.muscles[0].excitationAndActivation.y<<','<<p.muscles[1].excitationAndActivation.y<<','
                                 <<b.preProjectionPreStepConstraintDiagnostics.x<<','<<b.preProjectionPreStepConstraintDiagnostics.y<<','
                                 <<b.preProjectionPreStepConstraintDiagnostics.z<<','<<b.postProjectionPreStepConstraintDiagnostics.x<<','
                                 <<b.postProjectionPreStepConstraintDiagnostics.y<<','<<b.postProjectionPreStepConstraintDiagnostics.z<<','
                                 <<b.jointEqualityProjectionDiagnostics.x<<','<<b.jointEqualityProjectionDiagnostics.z<<','
                                 <<b.contactIterations<<'\n';
                            trace.flush();
                            if (trainingProfile) {
                                restingObserverProfile.respirationTraceMilliseconds +=
                                    profileElapsedMilliseconds(respirationTraceProfileStart);
                            }
                        }
                        if (restingComMomentumAudit &&
                            comMomentumObserverSample) {
                            // This is a post-acceptance CPU observation only.
                            // It never feeds q/v, the controller, or the next
                            // physical transaction.
                            const auto& articulation = rigid.model.articulations.front();
                            require(result.standStatuses.size() == 1u &&
                                        b.code == MR_NUMI_HUMAN_STAND_SUCCESS &&
                                        result.standQ.size() == articulation.nq &&
                                        result.standV.size() == articulation.nv &&
                                        result.standRootTranslations.size() == 1u &&
                                        result.standV.size() >= 3u,
                                    "accepted COM audit lacks a complete accepted endpoint");
                            const auto& root = result.standRootTranslations.front();
                            require(mrCompensatedTranslationValid(root),
                                    "accepted COM audit root translation is invalid");
                            std::vector<metalrobo::ArticulatedBodyKinematics>
                                qAuditAcceptedBodyKinematics;
                            std::vector<std::array<std::array<double, 3u>, 4u>>
                                qAuditSupportPointSlip;
                            std::array<std::array<double, 3u>, 5u>
                                qAuditSourceBodyLinearMomentum{};
                            if (qIntegrationAuditSample) {
                                const auto finiteDiagnosticVector = [](
                                    const std::vector<float>& values) {
                                    return std::all_of(values.begin(), values.end(),
                                        [](const float value) {
                                            return std::isfinite(value);
                                        });
                                };
                                const std::size_t fullEqualityCount =
                                    jointEqualityPayload.has_value()
                                        ? jointEqualityPayload->payload.records.size()
                                        : 0u;
                                const std::uint32_t releaseStep =
                                    separationReleaseStep.value_or(MR_INVALID_INDEX);
                                const bool releaseTailFitsPayload =
                                    separationReleaseEqualityQ.size() <= fullEqualityCount;
                                const std::size_t expectedActiveEqualityCount =
                                    releaseStep != MR_INVALID_INDEX && step > releaseStep &&
                                            releaseTailFitsPayload
                                        ? fullEqualityCount - separationReleaseEqualityQ.size()
                                        : fullEqualityCount;
                                require(step == qIntegrationWindow.firstAcceptedStep +
                                            qIntegrationAcceptedRows &&
                                            result.standPreProjectionQ.size() ==
                                                articulation.nq &&
                                            result.standPreProjectionV.size() ==
                                                articulation.nv &&
                                            result.standFreeVelocity.size() ==
                                                articulation.nv &&
                                            (!qIntegrationWindow.bounded ||
                                             (jointEqualityPayload.has_value() &&
                                              releaseTailFitsPayload &&
                                              result.standStatuses.size() == 1u &&
                                              result.standStatuses.front().jointEqualityCounts.x ==
                                                  expectedActiveEqualityCount &&
                                              result.standJointEqualityImpulses.size() ==
                                                  expectedActiveEqualityCount &&
                                              result.standSourceLimitImpulses.size() ==
                                                  articulation.nv &&
                                              finiteDiagnosticVector(
                                                  result.standFreeVelocity) &&
                                              finiteDiagnosticVector(
                                                  result.standJointEqualityImpulses) &&
                                              finiteDiagnosticVector(
                                                  result.standSourceLimitImpulses))) &&
                                            qBefore.size() == articulation.nq &&
                                            vBefore.size() == articulation.nv &&
                                            result.pointJacobians.size() ==
                                                queries.points.size() * 3u * articulation.nv &&
                                            queries.supportContacts.size() ==
                                                queries.supportSourceRecordIndices.size(),
                                        "accepted q-integration audit lacks a complete adjacent state, velocity, or point-Jacobian set");
                                const auto worldConfiguration = [](
                                    const std::span<const float> source,
                                    const MRCompensatedRootTranslationGPU& rootState) {
                                    require(source.size() >= 3u &&
                                                mrCompensatedTranslationValid(rootState),
                                            "stage momentum q/root translation is incomplete");
                                    std::vector<double> q(source.begin(), source.end());
                                    q[0] = double(rootState.reference.x) +
                                        rootState.displacement.x + rootState.correction.x;
                                    q[1] = double(rootState.reference.y) +
                                        rootState.displacement.y + rootState.correction.y;
                                    q[2] = double(rootState.reference.z) +
                                        rootState.displacement.z + rootState.correction.z;
                                    return q;
                                };
                                const auto widenedVelocity = [](
                                    const std::span<const float> source) {
                                    return std::vector<double>(source.begin(), source.end());
                                };
                                const std::vector<double> qBeforeWorld =
                                    worldConfiguration(qBefore, rootBefore);
                                const std::vector<double> qPreprojectionWorld =
                                    worldConfiguration(result.standPreProjectionQ, root);
                                const std::vector<double> qAcceptedWorld =
                                    worldConfiguration(result.standQ, root);
                                const std::vector<double> vBeforeWorld =
                                    widenedVelocity(vBefore);
                                const std::vector<double> vFreeWorld =
                                    widenedVelocity(result.standFreeVelocity);
                                const std::vector<double> vPreprojectionWorld =
                                    widenedVelocity(result.standPreProjectionV);
                                const std::vector<double> vAcceptedWorld =
                                    widenedVelocity(result.standV);
                                metalrobo::ArticulatedDynamicsConfig auditKinematicsConfig;
                                auditKinematicsConfig.gravity = {
                                    rigid.model.world.gravityAndTimestep.x,
                                    rigid.model.world.gravityAndTimestep.y,
                                    rigid.model.world.gravityAndTimestep.z};
                                auditKinematicsConfig.timestep =
                                    double(static_cast<float>(*muscleStepSeconds));
                                const auto sourceLinearMomentum = [&] (
                                    const std::span<const double> qState,
                                    const std::span<const double> vState,
                                    std::vector<metalrobo::ArticulatedBodyKinematics>*
                                        capturedBodyKinematics = nullptr) {
                                    std::vector<metalrobo::ArticulatedBodyKinematics>
                                        bodyKinematics(articulation.bodyCount);
                                    require(metalrobo::computeArticulatedBodyKinematics(
                                                rigid.model, 0u, qState, vState,
                                                bodyKinematics,
                                                auditKinematicsConfig).succeeded(),
                                            "accepted q-integration stage momentum kinematics failed");
                                    std::array<double, 3u> momentum{};
                                    double totalMass = 0.0;
                                    for (std::size_t body = 0u;
                                         body < bodyKinematics.size(); ++body) {
                                        const std::size_t bodyIndex =
                                            articulation.firstBody + body;
                                        const double mass = rigid.model.bodies[bodyIndex]
                                            .massAndInverseMass.x;
                                        require(std::isfinite(mass) && mass >= 0.0,
                                                "stage momentum body mass is invalid");
                                        totalMass += mass;
                                        for (std::size_t axis = 0u; axis < 3u; ++axis)
                                            momentum[axis] += mass *
                                                bodyKinematics[body].linearVelocity[axis];
                                    }
                                    require(std::isfinite(totalMass) && totalMass > 0.0 &&
                                                std::all_of(momentum.begin(), momentum.end(),
                                                    [](const double value) {
                                                        return std::isfinite(value);
                                                    }),
                                            "stage source-body linear momentum is invalid");
                                    if (capturedBodyKinematics != nullptr)
                                        *capturedBodyKinematics = std::move(bodyKinematics);
                                    return momentum;
                                };
                                qAuditSourceBodyLinearMomentum[0] =
                                    sourceLinearMomentum(qBeforeWorld, vBeforeWorld);
                                qAuditSourceBodyLinearMomentum[1] =
                                    sourceLinearMomentum(qBeforeWorld, vFreeWorld);
                                qAuditSourceBodyLinearMomentum[2] =
                                    sourceLinearMomentum(qBeforeWorld, vPreprojectionWorld);
                                qAuditSourceBodyLinearMomentum[3] =
                                    sourceLinearMomentum(qPreprojectionWorld,
                                        vPreprojectionWorld);
                                qAuditSourceBodyLinearMomentum[4] =
                                    sourceLinearMomentum(qAcceptedWorld, vAcceptedWorld,
                                        &qAuditAcceptedBodyKinematics);
                                const auto tangentialSlip = [&] (
                                    const std::array<double, 3u>& velocity,
                                    const std::array<std::array<double,3u>,3u>& basis) {
                                    const auto& auditTangent0=basis[1];const auto& auditTangent1=basis[2];
                                    require(std::all_of(velocity.begin(), velocity.end(),
                                                [](const double value) {
                                                    return std::isfinite(value);
                                                }),
                                            "q-integration support-point velocity is non-finite");
                                    const double tangent0Velocity =
                                        velocity[0] * auditTangent0[0] +
                                        velocity[1] * auditTangent0[1] +
                                        velocity[2] * auditTangent0[2];
                                    const double tangent1Velocity =
                                        velocity[0] * auditTangent1[0] +
                                        velocity[1] * auditTangent1[1] +
                                        velocity[2] * auditTangent1[2];
                                    const std::array<double, 3u> slip{
                                        tangent0Velocity, tangent1Velocity,
                                        std::hypot(tangent0Velocity, tangent1Velocity)};
                                    require(std::all_of(slip.begin(), slip.end(),
                                                [](const double value) {
                                                    return std::isfinite(value);
                                                }),
                                            "q-integration support-point slip is non-finite");
                                    return slip;
                                };
                                qAuditSupportPointSlip.resize(
                                    queries.supportContacts.size());
                                const std::array<std::span<const double>, 4u>
                                    linearizationStageVelocities{
                                        vBeforeWorld, vFreeWorld,
                                        vPreprojectionWorld, vAcceptedWorld};
                                for (std::size_t contact = 0u;
                                     contact < queries.supportContacts.size(); ++contact) {
                                    const auto& supportContact =
                                        queries.supportContacts[contact];
                                    const std::uint32_t sourceRecordIndex =
                                        sourceRecordIndexForSupportQuery(
                                            queries, *supportContactPayload, contact);
                                    const auto& sourceContact =
                                        supportContactPayload->records[sourceRecordIndex];
                                    // These identity fields bind the support-region row
                                    // to its contact-query slot. They do not imply that
                                    // the dynamic weighted-skin witness is a one-body
                                    // contact; the pre-step operator Jacobian for this
                                    // slot is the authoritative measured linearization.
                                    require(supportContact.sourceGeometryIndex ==
                                                sourceContact.sourceGeometryIndex,
                                            "q-integration support point query lost source geometry identity");
                                    const std::uint32_t pointIndex =
                                        supportContact.pointQueryIndex;
                                    for (std::size_t stage = 0u; stage <
                                            linearizationStageVelocities.size(); ++stage) {
                                        std::array<double, 3u> pointVelocity{};
                                        for (std::size_t axis = 0u; axis < 3u; ++axis)
                                            for (std::size_t dof = 0u; dof < articulation.nv; ++dof)
                                                pointVelocity[axis] +=
                                                    double(result.pointJacobians[
                                                        (std::size_t(pointIndex) * 3u + axis) *
                                                            articulation.nv + dof]) *
                                                    linearizationStageVelocities[stage][dof];
                                        qAuditSupportPointSlip[contact][stage] =
                                            tangentialSlip(pointVelocity,acceptedContactBasis(
                                                result,contact,queries.supportContacts.size(),(!restingBedSurface.empty()||NumiHumanRestingRopeSupport::configuredFromEnvironment()),
                                                {supportContactPayload->header.groundNormalX,
                                                 supportContactPayload->header.groundNormalY,
                                                 supportContactPayload->header.groundNormalZ}));
                                    }
                                }
                                if (qIntegrationWindow.bounded) {
                                    require(qSupportSlipTrace.good(),
                                            "bounded accepted Q support-slip trace is unavailable");
                                    for (std::size_t contact = 0u;
                                         contact < qAuditSupportPointSlip.size(); ++contact) {
                                        const auto& supportContact =
                                            queries.supportContacts[contact];
                                        const std::uint32_t sourceRecordIndex =
                                            sourceRecordIndexForSupportQuery(
                                                queries, *supportContactPayload, contact);
                                        const auto& sourceContact =
                                            supportContactPayload->records[sourceRecordIndex];
                                        qSupportSlipTrace << step << ','
                                            << std::setprecision(17)
                                            << step * double(coupled.physiology.runtime.timestepSeconds())
                                            << ',' << contact << ',' << sourceRecordIndex
                                            << ',' << supportContact.bodyIndex
                                            << ',' << sourceContact.sourceGeometryIndex
                                            << ',' << supportContact.pointQueryIndex;
                                        for (const auto& slip : qAuditSupportPointSlip[contact])
                                            qSupportSlipTrace << ',' << slip[0] << ','
                                                << slip[1] << ',' << slip[2];
                                        qSupportSlipTrace << '\n';
                                    }
                                    qSupportSlipTrace.flush();
                                    require(qSupportSlipTrace.good(),
                                            "bounded accepted Q support-slip write failed");
                                    ++qSupportSlipSampleSteps;
                                }
                                const auto writeFloatArray = [](std::ostream& output,
                                                                std::span<const float> values) {
                                    output << std::setprecision(
                                        std::numeric_limits<float>::max_digits10);
                                    for (std::size_t i = 0u; i < values.size(); ++i) {
                                        if (i != 0u) output << ';';
                                        output << values[i];
                                    }
                                };
                                const auto writeRootVector = [](std::ostream& output,
                                                                const MRCompensatedRootTranslationGPU& value) {
                                    output << std::setprecision(
                                        std::numeric_limits<float>::max_digits10)
                                        << value.reference.x << ';' << value.reference.y << ';'
                                        << value.reference.z << ';' << value.reference.w << ';'
                                        << value.displacement.x << ';' << value.displacement.y << ';'
                                        << value.displacement.z << ';' << value.displacement.w << ';'
                                        << value.correction.x << ';' << value.correction.y << ';'
                                        << value.correction.z << ';' << value.correction.w;
                                };
                                const auto payloadFingerprint = [](std::span<const float> values) {
                                    return metalrobo::numiHumanRuntimePayloadFingerprint(
                                        std::as_bytes(values));
                                };
                                const auto qIntegrationCsvProfileStart = trainingProfile
                                    ? std::chrono::steady_clock::now()
                                    : std::chrono::steady_clock::time_point{};
                                qIntegrationTrace << step << ','
                                    << std::setprecision(17)
                                    << step * double(coupled.physiology.runtime.timestepSeconds()) << ','
                                    << static_cast<double>(static_cast<float>(*muscleStepSeconds)) << ','
                                    << result.standQ.size() << ',' << result.standV.size() << ',';
                                writeFloatArray(qIntegrationTrace, qBefore);
                                qIntegrationTrace << ',';
                                writeFloatArray(qIntegrationTrace, vBefore);
                                qIntegrationTrace << ',';
                                writeFloatArray(qIntegrationTrace, result.standPreProjectionQ);
                                qIntegrationTrace << ',';
                                writeFloatArray(qIntegrationTrace, result.standPreProjectionV);
                                qIntegrationTrace << ',';
                                writeFloatArray(qIntegrationTrace, result.standQ);
                                qIntegrationTrace << ',';
                                writeFloatArray(qIntegrationTrace, result.standV);
                                qIntegrationTrace << ',';
                                writeRootVector(qIntegrationTrace, rootBefore);
                                qIntegrationTrace << ',';
                                writeRootVector(qIntegrationTrace, root);
                                qIntegrationTrace << ','
                                    << payloadFingerprint(qBefore) << ','
                                    << payloadFingerprint(vBefore) << ','
                                    << payloadFingerprint(result.standPreProjectionQ) << ','
                                    << payloadFingerprint(result.standPreProjectionV) << ','
                                    << payloadFingerprint(result.standQ) << ','
                                    << payloadFingerprint(result.standV);
                                qIntegrationTrace << std::setprecision(
                                    std::numeric_limits<double>::max_digits10);
                                for (const auto& stageMomentum :
                                     qAuditSourceBodyLinearMomentum)
                                    for (const double component : stageMomentum)
                                        qIntegrationTrace << ',' << component;
                                const std::size_t nv = articulation.nv;
                                if (qIntegrationWindow.bounded) {
                                    require(result.standBodyKineticRootMassRows.size() ==
                                                3u * nv &&
                                            result.standBodyKineticRootMomentumStages.size() == 9u,
                                            "bounded Q row lacks GPU root body-kinetic momentum evidence");
                                    for (const float component :
                                         result.standBodyKineticRootMomentumStages)
                                        qIntegrationTrace << ',' << component;
                                    const std::span<const float> rootRows(
                                        result.standBodyKineticRootMassRows);
                                    for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                        qIntegrationTrace << ',';
                                        writeFloatArray(qIntegrationTrace,
                                            rootRows.subspan(axis * nv, nv));
                                    }
                                } else {
                                    for (std::size_t column = 0u; column < 9u; ++column)
                                        qIntegrationTrace << ',';
                                }
                                // These diagnostics were already read back by the
                                // bounded Q-window result path. Keep their full
                                // vectors out of unbounded traces.
                                const bool captureConstraintVectors =
                                    qIntegrationWindow.bounded;
                                qIntegrationTrace << ','
                                    << (captureConstraintVectors ? 1 : 0) << ','
                                    << (captureConstraintVectors
                                            ? result.standFreeVelocity.size() : 0u) << ',';
                                if (captureConstraintVectors)
                                    writeFloatArray(qIntegrationTrace,
                                        result.standFreeVelocity);
                                qIntegrationTrace << ','
                                    << (captureConstraintVectors
                                            ? result.standJointEqualityImpulses.size() : 0u) << ',';
                                if (captureConstraintVectors)
                                    writeFloatArray(qIntegrationTrace,
                                        result.standJointEqualityImpulses);
                                qIntegrationTrace << ','
                                    << (captureConstraintVectors
                                            ? result.standSourceLimitImpulses.size() : 0u) << ',';
                                if (captureConstraintVectors)
                                    writeFloatArray(qIntegrationTrace,
                                        result.standSourceLimitImpulses);
                                qIntegrationTrace << '\n';
                                qIntegrationTrace.flush();
                                require(qIntegrationTrace.good(),
                                        "accepted q-integration trace write failed");
                                if (restingAcceptedForceAudit) {
                                    require(result.layout.mujocoMuscleElements ==
                                                musclePayload.gpuMuscles.size() &&
                                                result.layout.standTendonBindingElements ==
                                                    musclePayload.tendonPayload.bindings.size() &&
                                                result.layout.mujocoMuscleGeneralizedForceElements ==
                                                    result.mujocoMuscleGeneralizedForces.size() &&
                                                result.layout.mujocoGeneralizedForceElements ==
                                                    result.mujocoGeneralizedForces.size() &&
                                                result.layout.standTendonCorrectionElements ==
                                                    result.standTendonGeneralizedCorrections.size(),
                                            "accepted force observer source counts/layout differ from the loaded MyoSim/tendon payloads");
                                    // The reducer initially writes the force-workspace
                                    // slice as the sum of per-muscle rows. An optional
                                    // pre-dynamics consumer may then add its own
                                    // correction in place. Tendon-transfer rows remain
                                    // separate source-to-distributed generalized-force
                                    // corrections, so neither value is mislabeled as a
                                    // global net force.
                                    metalrobo::human::observer::
                                        AcceptedGeneralizedForceSummary forceSummary;
                                    std::string_view forceSummaryError;
                                    require(metalrobo::human::observer::
                                                summarizeAcceptedGeneralizedForceRows(
                                                    result.mujocoMuscleGeneralizedForces,
                                                    result.mujocoGeneralizedForces,
                                                    result.standTendonGeneralizedCorrections,
                                                    musclePayload.gpuMuscles.size(),
                                                    musclePayload.tendonPayload.bindings.size(),
                                                    articulation.nv,
                                                    forceSummary,
                                                    forceSummaryError),
                                            "accepted force observer result layout/value check failed: " +
                                                std::string(forceSummaryError));
                                    const auto writeDoubleArray = [](
                                        std::ostream& output,
                                        const std::span<const double> values) {
                                        output << std::setprecision(
                                            std::numeric_limits<double>::max_digits10);
                                        for (std::size_t index = 0u;
                                             index < values.size(); ++index) {
                                            if (index != 0u) output << ';';
                                            output << values[index];
                                        }
                                    };
                                    acceptedForceTrace << step << ','
                                        << std::setprecision(17)
                                        << step * double(
                                            coupled.physiology.runtime.timestepSeconds())
                                        << ',' << payloadFingerprint(qBefore) << ','
                                        << articulation.nv << ','
                                        << musclePayload.gpuMuscles.size() << ','
                                        << musclePayload.tendonPayload.bindings.size() << ',';
                                    writeDoubleArray(acceptedForceTrace,
                                        forceSummary.muscleRowsByDof);
                                    acceptedForceTrace << ',';
                                    writeDoubleArray(acceptedForceTrace,
                                        forceSummary.tendonCorrectionsByDof);
                                    acceptedForceTrace << ',';
                                    writeFloatArray(acceptedForceTrace,
                                        result.mujocoGeneralizedForces);
                                    acceptedForceTrace << ',';
                                    acceptedForceTrace <<
                                        "N for translational generalized coordinates; "
                                        "N*m for rotational generalized coordinates; "
                                        "DOF identity is local_v_index in resting-com-q-index-map.csv";
                                    acceptedForceTrace << '\n';
                                    acceptedForceTrace.flush();
                                    require(acceptedForceTrace.good(),
                                            "accepted force observer row write failed");
                                    ++acceptedForceAuditRows;
                                }
                                ++qIntegrationAcceptedRows;
                                if (trainingProfile) {
                                    restingObserverProfile.qIntegrationCsvMilliseconds +=
                                        profileElapsedMilliseconds(qIntegrationCsvProfileStart);
                                }
                            }
                            if (comMomentumObserverSample) {
                            const auto comCpuProfileStart = trainingProfile
                                ? std::chrono::steady_clock::now()
                                : std::chrono::steady_clock::time_point{};
                            // The opt-in body-motion CSV is nested inside this broader
                            // accepted-COM interval. Track it separately so profile fields
                            // remain exclusive when observer accounting subtracts them.
                            double bodyMotionCsvElapsedMilliseconds = 0.0;
                            std::vector<double> q(result.standQ.begin(), result.standQ.end());
                            q[0] = double(root.reference.x) + root.displacement.x + root.correction.x;
                            q[1] = double(root.reference.y) + root.displacement.y + root.correction.y;
                            q[2] = double(root.reference.z) + root.displacement.z + root.correction.z;
                            const std::vector<double> v(result.standV.begin(), result.standV.end());
                            std::vector<metalrobo::ArticulatedBodyKinematics> bodyKinematics;
                            if (qIntegrationAuditSample) {
                                require(qAuditAcceptedBodyKinematics.size() ==
                                            articulation.bodyCount,
                                        "accepted q-audit kinematics were not retained for COM");
                                bodyKinematics = std::move(
                                    qAuditAcceptedBodyKinematics);
                            } else {
                                bodyKinematics.resize(articulation.bodyCount);
                                metalrobo::ArticulatedDynamicsConfig kinematicsConfig;
                                kinematicsConfig.gravity = {
                                    rigid.model.world.gravityAndTimestep.x,
                                    rigid.model.world.gravityAndTimestep.y,
                                    rigid.model.world.gravityAndTimestep.z};
                                kinematicsConfig.timestep =
                                    double(static_cast<float>(*muscleStepSeconds));
                                require(metalrobo::computeArticulatedBodyKinematics(
                                            rigid.model, 0u, q, v, bodyKinematics,
                                            kinematicsConfig).succeeded(),
                                        "accepted COM CPU kinematics evaluation failed");
                            }
                            std::array<double, 3u> comPosition{};
                            std::array<double, 3u> comVelocity{};
                            double totalMass = 0.0;
                            require(bodyKinematics.size() == articulation.bodyCount,
                                    "accepted COM kinematics body count changed");
                            if (restingAcceptedBodyMotionAudit &&
                                normalObserverSample) {
                                require(step > 0u,
                                        "accepted body motion observer requires a physical step");
                                const auto motionCsvStart = trainingProfile
                                    ? std::chrono::steady_clock::now()
                                    : std::chrono::steady_clock::time_point{};
                                std::vector<double> bodyMasses;
                                bodyMasses.reserve(bodyKinematics.size());
                                for (std::size_t body = 0u;
                                     body < bodyKinematics.size(); ++body) {
                                    const std::size_t bodyIndex =
                                        articulation.firstBody + body;
                                    require(bodyIndex < rigid.model.bodies.size(),
                                            "accepted body motion observer body index is invalid");
                                    bodyMasses.push_back(rigid.model.bodies[bodyIndex]
                                        .massAndInverseMass.x);
                                }
                                const std::array<double, 3u> rootTranslation{
                                    q[0], q[1], q[2]};
                                const auto motionRows =
                                    metalrobo::human::observer::makeBodyMotionPartition(
                                        bodyKinematics, bodyMasses,
                                        articulation.firstBody, rootTranslation);
                                const double acceptedTime =
                                    double(step) * double(static_cast<float>(
                                        coupled.physiology.runtime.timestepSeconds()));
                                for (const auto& row : motionRows) {
                                    bodyMotionPartitionTrace << step << ','
                                        << acceptedTime << ',' << row.bodyIndex << ',';
                                    const std::string bodyName =
                                        row.bodyIndex < rigid.model.bodyNames.size()
                                            ? rigid.model.bodyNames[row.bodyIndex]
                                            : std::string("unnamed");
                                    writeMotionCsvString(bodyMotionPartitionTrace, bodyName);
                                    bodyMotionPartitionTrace << ',' << row.massKg << ','
                                        << rootTranslation[0] << ',' << rootTranslation[1]
                                        << ',' << rootTranslation[2];
                                    for (const double value :
                                         row.centerOfMassRelativeToRootMeters)
                                        bodyMotionPartitionTrace << ',' << value;
                                    for (const double value :
                                         row.massWeightedRelativeComKgMeters)
                                        bodyMotionPartitionTrace << ',' << value;
                                    for (const double value :
                                         row.orientationBodyToWorldXyzw)
                                        bodyMotionPartitionTrace << ',' << value;
                                    for (const double value :
                                         row.linearVelocityWorldMetersPerSecond)
                                        bodyMotionPartitionTrace << ',' << value;
                                    for (const double value :
                                         row.angularVelocityWorldRadiansPerSecond)
                                        bodyMotionPartitionTrace << ',' << value;
                                    for (const double value :
                                         row.linearMomentumKgMetersPerSecond)
                                        bodyMotionPartitionTrace << ',' << value;
                                    bodyMotionPartitionTrace << '\n';
                                }
                                const std::size_t nv = articulation.nv;
                                const std::size_t queryElements =
                                    queries.points.size() * 3u * nv;
                                require(result.standPreviousVelocity.size() == nv &&
                                            result.pointJacobians.size() == queryElements &&
                                            result.pointWorld.size() == queries.points.size() &&
                                            result.pointPositionLow.size() == queries.points.size() &&
                                            queries.supportContacts.size() ==
                                                queries.supportSourceRecordIndices.size(),
                                        "accepted support motion observer lacks same-step pre-dynamics arrays");
                                const auto preVelocityFingerprint =
                                    metalrobo::numiHumanRuntimePayloadFingerprint(
                                        std::as_bytes(std::span<const float>(
                                            result.standPreviousVelocity.data(),
                                            result.standPreviousVelocity.size())));
                                const std::array<double, 3u> groundNormal{
                                    supportContactPayload->header.groundNormalX,
                                    supportContactPayload->header.groundNormalY,
                                    supportContactPayload->header.groundNormalZ};
                                for (std::size_t contact = 0u;
                                     contact < queries.supportContacts.size(); ++contact) {
                                    const auto& contactQuery =
                                        queries.supportContacts[contact];
                                    const std::uint32_t sourceRecordIndex =
                                        sourceRecordIndexForSupportQuery(
                                            queries, *supportContactPayload, contact);
                                    const auto& sourceContact =
                                        supportContactPayload->records[sourceRecordIndex];
                                    require(contactQuery.sourceGeometryIndex ==
                                                sourceContact.sourceGeometryIndex,
                                            "accepted support motion observer source geometry identity changed");
                                    const auto pointVelocity =
                                        metalrobo::human::observer::makeSupportPointVelocity(
                                            result.pointJacobians,
                                            contactQuery.pointQueryIndex,
                                            static_cast<std::uint32_t>(nv),
                                            result.standPreviousVelocity, acceptedContactBasis(
                                                result,contact,queries.supportContacts.size(),
                                                (!restingBedSurface.empty()||NumiHumanRestingRopeSupport::configuredFromEnvironment()),groundNormal)[0]);
                                    const auto& point =
                                        result.pointWorld[contactQuery.pointQueryIndex].position;
                                    const auto& low =
                                        result.pointPositionLow[contactQuery.pointQueryIndex];
                                    const double pointX = double(point.x + low.x);
                                    const double pointY = double(point.y + low.y);
                                    const double pointZ = double(point.z + low.z);
                                    const double observerDt = double(
                                        static_cast<float>(*muscleStepSeconds));
                                    supportPointMotionTrace << step << ','
                                        << double(step) * observerDt << ','
                                        << step - 1u << ','
                                        << double(step - 1u) * observerDt << ','
                                        << contact << ','
                                        << sourceContact.sourceGeometryIndex << ','
                                        << contactQuery.bodyIndex << ','
                                        << contactQuery.pointQueryIndex << ','
                                        << pointX << ',' << pointY << ',' << pointZ << ','
                                        << preVelocityFingerprint << ','
                                        << pointVelocity.worldMetersPerSecond[0] << ','
                                        << pointVelocity.worldMetersPerSecond[1] << ','
                                        << pointVelocity.worldMetersPerSecond[2] << ','
                                        << pointVelocity.tangent0MetersPerSecond << ','
                                        << pointVelocity.tangent1MetersPerSecond << ','
                                        << pointVelocity.tangentialSpeedMetersPerSecond << ','
                                        << "pre_step_point_J_times_stand_previous_velocity\n";
                                }
                                bodyMotionPartitionTrace.flush();
                                supportPointMotionTrace.flush();
                                require(bodyMotionPartitionTrace.good() &&
                                            supportPointMotionTrace.good(),
                                        "accepted body motion observer CSV write failed");
                                if (trainingProfile) {
                                    bodyMotionCsvElapsedMilliseconds =
                                        profileElapsedMilliseconds(motionCsvStart);
                                    restingObserverProfile.bodyMotionCsvMilliseconds +=
                                        bodyMotionCsvElapsedMilliseconds;
                                }
                            }
                            for (std::size_t body = 0u; body < bodyKinematics.size(); ++body) {
                                const auto bodyIndex = articulation.firstBody +
                                    static_cast<std::uint32_t>(body);
                                const double mass =
                                    rigid.model.bodies[bodyIndex].massAndInverseMass.x;
                                require(std::isfinite(mass) && mass >= 0.0,
                                        "accepted COM audit body mass is invalid");
                                totalMass += mass;
                                for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                    comPosition[axis] += mass *
                                        bodyKinematics[body].centerOfMassPosition[axis];
                                    comVelocity[axis] += mass *
                                        bodyKinematics[body].linearVelocity[axis];
                                }
                            }
                            require(std::isfinite(totalMass) && totalMass > 0.0,
                                    "accepted COM audit total mass is invalid");
                            for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                comPosition[axis] /= totalMass;
                                comVelocity[axis] /= totalMass;
                            }
                            const std::array<double, 3u> comMomentum{
                                totalMass * comVelocity[0], totalMass * comVelocity[1],
                                totalMass * comVelocity[2]};
                            if (trainingProfile) {
                                const double comCpuElapsedMilliseconds =
                                    profileElapsedMilliseconds(comCpuProfileStart);
                                restingObserverProfile.comCpuKinematicsMilliseconds +=
                                    std::max(0.0, comCpuElapsedMilliseconds -
                                        bodyMotionCsvElapsedMilliseconds);
                            }
                            const bool deltaValid = havePreviousComSample &&
                                step > previousComSampleStep;
                            const std::uint32_t sampleStartStep =
                                havePreviousComSample ? previousComSampleStep : 0u;
                            const std::uint32_t sampleSteps =
                                step > sampleStartStep ? step - sampleStartStep : 0u;
                            const bool qSampleRequiresAdjacentPrevious =
                                qIntegrationAuditSample &&
                                (step != qIntegrationWindow.firstAcceptedStep ||
                                 qIntegrationWindow.firstAcceptedStep > 1u);
                            if (qSampleRequiresAdjacentPrevious) {
                                require(deltaValid && sampleSteps == 1u,
                                        "accepted Q-window COM row lacks its immediately preceding accepted state");
                            }
                            std::array<double, 3u> deltaComMomentum{};
                            if (deltaValid) {
                                for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                    deltaComMomentum[axis] =
                                        comMomentum[axis] - previousComMomentum[axis];
                                }
                            }
                            const double h = double(static_cast<float>(*muscleStepSeconds));
                            const double normalImpulse =
                                double(b.contactAndAcceleration.z);
                            const auto& supportNormal = supportContactPayload->header;
                            const bool fullContactVector =
                                result.standContactImpulses.size() ==
                                3u * queries.supportContacts.size() &&
                                queries.supportContacts.size() ==
                                    queries.supportSourceRecordIndices.size();
                            require(fullContactVector,
                                    "accepted COM audit lacks every support-contact impulse triple");
                            const std::array<double,3u> referencePlaneNormal{
                                supportNormal.groundNormalX,supportNormal.groundNormalY,supportNormal.groundNormalZ};
                            std::array<double, 3u> worldExternalSupportImpulse{};
                            std::uint32_t designatedInternalSeamRowCount=0u;
                            for (std::size_t contact = 0u;
                                 contact < queries.supportContacts.size(); ++contact) {
                                const std::uint32_t sourceRecordIndex =
                                    sourceRecordIndexForSupportQuery(
                                        queries, *supportContactPayload, contact);
                                const auto impulseBasis=acceptedContactBasis(result,contact,
                                    queries.supportContacts.size(),(!restingBedSurface.empty()||NumiHumanRestingRopeSupport::configuredFromEnvironment()),referencePlaneNormal);
                                const double normalComponent =
                                    result.standContactImpulses[3u * contact];
                                const double tangent0Component =
                                    result.standContactImpulses[3u * contact + 1u];
                                const double tangent1Component =
                                    result.standContactImpulses[3u * contact + 2u];
                                require(std::isfinite(normalComponent) &&
                                            std::isfinite(tangent0Component) &&
                                            std::isfinite(tangent1Component),
                                        "accepted support impulse component is non-finite");
                                if (comAuditInternalSeamRows.at(sourceRecordIndex)) {
                                    ++designatedInternalSeamRowCount;
                                } else {
                                    for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                        worldExternalSupportImpulse[axis] +=
                                            normalComponent * impulseBasis[0][axis] +
                                            tangent0Component * impulseBasis[1][axis] +
                                            tangent1Component * impulseBasis[2][axis];
                                    }
                                }
                            }
                            const auto qFingerprint =
                                metalrobo::numiHumanRuntimePayloadFingerprint(
                                    std::as_bytes(std::span<const float>(
                                        result.standQ.data(), result.standQ.size())));
                            const auto vFingerprint =
                                metalrobo::numiHumanRuntimePayloadFingerprint(
                                    std::as_bytes(std::span<const float>(
                                        result.standV.data(), result.standV.size())));
                            const auto rootFingerprint =
                                metalrobo::numiHumanRuntimePayloadFingerprint(
                                    std::as_bytes(std::span<const MRCompensatedRootTranslationGPU>(
                                        &root, 1u)));
                            const std::array<double, 3u> gravity{
                                rigid.model.world.gravityAndTimestep.x,
                                rigid.model.world.gravityAndTimestep.y,
                                rigid.model.world.gravityAndTimestep.z};
                            std::array<double, 3u> unaccountedDeltaP{};
                            const bool hasPerStepRemainder = deltaValid && sampleSteps == 1u;
                            if (hasPerStepRemainder) {
                                for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                    const double gravityImpulse =
                                        totalMass * gravity[axis] * h;
                                    unaccountedDeltaP[axis] =
                                        deltaComMomentum[axis] - gravityImpulse -
                                        worldExternalSupportImpulse[axis];
                                }
                            }
                            // These GPU root-momentum stages use the same mass rows
                            // assembled at the pre-step configuration. The free and
                            // post-constraint stages therefore isolate the solver's
                            // same-q impulse response from the CPU endpoint q/v product.
                            const std::size_t momentumNv = articulation.nv;
                            const auto& gpuRootMassRows =
                                result.standBodyKineticRootMassRows;
                            const auto& gpuRootMomentumStages =
                                result.standBodyKineticRootMomentumStages;
                            const bool gpuRootMomentumSameQAvailable =
                                gpuRootMassRows.size() == 3u * momentumNv &&
                                (gpuRootMomentumStages.size() == 6u ||
                                 gpuRootMomentumStages.size() == 9u) &&
                                result.standPreviousVelocity.size() == momentumNv &&
                                result.standV.size() == momentumNv;
                            std::array<double, 3u> gpuFreeMomentumSameQ{};
                            std::array<double, 3u> gpuPostConstraintsMomentumSameQ{};
                            std::array<double, 3u> gpuPreviousVelocityMomentumSameQ{};
                            std::array<double, 3u> gpuAcceptedVelocityMomentumSameQ{};
                            std::array<double, 3u> sameQPostConstraintImpulseResidual{};
                            std::array<double, 3u> sameQAcceptedImpulseResidual{};
                            std::array<double, 3u> endpointConfigurationMomentumDelta{};
                            const bool gpuAcceptedEndpointMomentumAvailable =
                                gpuRootMomentumStages.size() == 9u;
                            const bool endpointMomentumCaptureExpected =
                                restingComMomentumAudit &&
                                qIntegrationWindow.bounded &&
                                step >= qIntegrationWindow.firstAcceptedStep &&
                                step <= qIntegrationWindow.lastAcceptedStep;
                            require(gpuAcceptedEndpointMomentumAvailable ==
                                        endpointMomentumCaptureExpected,
                                    "accepted endpoint GPU momentum capture does not match the pinned audit window");
                            std::array<double, 3u> gpuAcceptedEndpointMomentum{};
                            std::array<double, 3u> endpointGpuMinusSameQAccepted{};
                            std::array<double, 3u> endpointGpuMinusCpuCom{};
                            if (gpuAcceptedEndpointMomentumAvailable) {
                                for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                    gpuAcceptedEndpointMomentum[axis] =
                                        double(gpuRootMomentumStages[6u + axis]);
                                    endpointGpuMinusCpuCom[axis] =
                                        gpuAcceptedEndpointMomentum[axis] - comMomentum[axis];
                                }
                            }
                            if (gpuRootMomentumSameQAvailable) {
                                for (std::size_t axis = 0u; axis < 3u; ++axis) {
                                    gpuFreeMomentumSameQ[axis] =
                                        double(gpuRootMomentumStages[axis]);
                                    gpuPostConstraintsMomentumSameQ[axis] =
                                        double(gpuRootMomentumStages[3u + axis]);
                                    double previousSameQ = 0.0;
                                    double acceptedSameQ = 0.0;
                                    for (std::size_t dof = 0u; dof < momentumNv; ++dof) {
                                        const double massRow = double(
                                            gpuRootMassRows[axis * momentumNv + dof]);
                                        previousSameQ = std::fma(massRow,
                                            double(result.standPreviousVelocity[dof]),
                                            previousSameQ);
                                        acceptedSameQ = std::fma(massRow,
                                            double(result.standV[dof]), acceptedSameQ);
                                    }
                                    gpuPreviousVelocityMomentumSameQ[axis] = previousSameQ;
                                    gpuAcceptedVelocityMomentumSameQ[axis] = acceptedSameQ;
                                    sameQPostConstraintImpulseResidual[axis] =
                                        gpuPostConstraintsMomentumSameQ[axis] -
                                        gpuFreeMomentumSameQ[axis] -
                                        worldExternalSupportImpulse[axis];
                                    sameQAcceptedImpulseResidual[axis] =
                                        acceptedSameQ - gpuFreeMomentumSameQ[axis] -
                                        worldExternalSupportImpulse[axis];
                                    endpointConfigurationMomentumDelta[axis] =
                                        comMomentum[axis] - acceptedSameQ;
                                    if (gpuAcceptedEndpointMomentumAvailable) {
                                        endpointGpuMinusSameQAccepted[axis] =
                                            gpuAcceptedEndpointMomentum[axis] - acceptedSameQ;
                                    }
                                }
                            }
                            const auto comCsvProfileStart = trainingProfile
                                ? std::chrono::steady_clock::now()
                                : std::chrono::steady_clock::time_point{};
                            comMomentumTrace << sampleStartStep << ','
                                << step << ','
                                << step * double(coupled.physiology.runtime.timestepSeconds()) << ','
                                << sampleSteps << ','
                                << totalMass << ','
                                << comPosition[0] << ',' << comPosition[1] << ',' << comPosition[2] << ','
                                << comVelocity[0] << ',' << comVelocity[1] << ',' << comVelocity[2] << ','
                                << comMomentum[0] << ',' << comMomentum[1] << ',' << comMomentum[2] << ',';
                            if (deltaValid) {
                                comMomentumTrace << deltaComMomentum[0] << ','
                                    << deltaComMomentum[1] << ',' << deltaComMomentum[2];
                            } else {
                                comMomentumTrace << ",,";
                            }
                            comMomentumTrace << ',' << (deltaValid ? 1 : 0) << ','
                                << totalMass * rigid.model.world.gravityAndTimestep.x * h * sampleSteps << ','
                                << totalMass * rigid.model.world.gravityAndTimestep.y * h * sampleSteps << ','
                                << totalMass * rigid.model.world.gravityAndTimestep.z * h * sampleSteps << ','
                                << result.standV[0] << ',' << result.standV[1] << ','
                                << result.standV[2] << ','
                                << supportNormal.groundNormalX << ','
                                << supportNormal.groundNormalY << ','
                                << supportNormal.groundNormalZ << ','
                                << normalImpulse << ',' << normalImpulse / h << ','
                                << b.constraintImpulseDiagnostics.x << ','
                                << b.constraintImpulseDiagnostics.y << ','
                                << b.activeContactCount << ','
                                << result.standContactImpulses.size() << ','
                                << (fullContactVector ? 1 : 0) << ','
                                << designatedInternalSeamRowCount << ','
                                << worldExternalSupportImpulse[0] << ','
                                << worldExternalSupportImpulse[1] << ','
                                << worldExternalSupportImpulse[2] << ',';
                            if (hasPerStepRemainder) {
                                comMomentumTrace << unaccountedDeltaP[0] << ','
                                    << unaccountedDeltaP[1] << ',' << unaccountedDeltaP[2];
                            } else {
                                comMomentumTrace << ",,";
                            }
                            comMomentumTrace << ',' << qFingerprint << ','
                                << vFingerprint << ',' << rootFingerprint << ','
                                << (hasPerStepRemainder
                                    ? "per_step_delta_p_minus_gravity_and_external_support_only_internal_seam_excluded"
                                    : "not_per_step_or_initial_sample");
                            // These existing GPU accumulators use the contact solver's
                            // actual skin-support Jacobians. They are sums over the
                            // accepted segment's solver iterates, not an endpoint
                            // mechanical-energy balance or a static contact proxy.
                            const auto& work = b.constraintImpulseWorkDiagnostics;
                            const auto& absoluteWork = b.constraintImpulseAbsoluteWorkDiagnostics;
                            const std::array<double, 4u> signedValues{
                                work.x, work.y, work.z, work.w};
                            const std::array<double, 4u> absoluteValues{
                                absoluteWork.x, absoluteWork.y, absoluteWork.z, absoluteWork.w};
                            for (std::size_t family = 0u; family < signedValues.size(); ++family) {
                                require(std::isfinite(signedValues[family]) &&
                                            std::isfinite(absoluteValues[family]) &&
                                            absoluteValues[family] >= 0.0 &&
                                            absoluteValues[family] + 1.0e-6 *
                                                std::max(1.0, absoluteValues[family]) >=
                                                std::abs(signedValues[family]),
                                        "accepted solver-iterate work diagnostic is invalid");
                                comMomentumTrace << ',' << signedValues[family];
                            }
                            for (const double value : absoluteValues)
                                comMomentumTrace << ',' << value;
                            const auto writeMomentumTriple = [&](const
                                std::array<double, 3u>& values) {
                                for (const double value : values) {
                                    comMomentumTrace << ',';
                                    if (gpuRootMomentumSameQAvailable)
                                        comMomentumTrace << value;
                                }
                            };
