                      << " final_subtalar_r=" << (muscleDrivenState.has_value()
                              ? muscleDrivenState->finalFootCoordinates[1] : 0.0)
                      << " final_mtp_r=" << (muscleDrivenState.has_value()
                              ? muscleDrivenState->finalFootCoordinates[2] : 0.0)
                      << " final_ankle_l=" << (muscleDrivenState.has_value()
                              ? muscleDrivenState->finalFootCoordinates[3] : 0.0)
                      << " final_subtalar_l=" << (muscleDrivenState.has_value()
                              ? muscleDrivenState->finalFootCoordinates[4] : 0.0)
                      << " final_mtp_l=" << (muscleDrivenState.has_value()
                              ? muscleDrivenState->finalFootCoordinates[5] : 0.0)
                      << " source_support_contact=" << (sourceSupportContact ? "true" : "false")
                      << " source_support_witnesses=" << (sourceSupportContact
                              ? muscleDrivenState->supportWitnessCount : 0u)
                      << " source_support_active_contacts=" << (sourceSupportContact
                              ? muscleDrivenState->activeSupportContactCount : 0u)
                      << " source_support_max_active_contacts=" << (sourceSupportContact
                              ? muscleDrivenState->maximumActiveSupportContactCount : 0u)
                      << " source_support_min_plane_gap_m=" << (sourceSupportContact
                              ? muscleDrivenState->minimumSupportPlaneGapMeters : 0.0)
                      << " source_support_seed_translation_m=" << (sourceSupportContact
                              ? muscleDrivenState->supportSeedTranslationMeters : 0.0)
                      << " source_support_metal_device=\"" << (sourceSupportContact
                              ? muscleDrivenState->supportDeviceName : "none") << "\""
                      << " source_support_metal_status=" << (sourceSupportContact
                              ? muscleDrivenState->supportMetalStatus : "not_requested")
                      << " source_support_metal_elapsed_ms=" << (sourceSupportContact
                              ? muscleDrivenState->supportGpuElapsedMilliseconds : 0.0)
                      << " source_support_max_gpu_cpu_velocity_error=" << (sourceSupportContact
                              ? muscleDrivenState->supportMaximumGpuCpuVelocityError : 0.0)
                      << " boundary=" << evidenceBoundary
                      << " route_geometry=" << (sourceRouteCentrelines
                              ? (surfaceProjectSourceSites
                                  ? "cpu_fp64_mujoco_tangent_and_wrapped_arc_centreline_at_same_q_with_visual_only_nearest_bodyparts3d_triangle_source_site_projection_not_a_force_path_or_tendon_surface_certificate"
                                  : "cpu_fp64_mujoco_tangent_and_wrapped_arc_centreline_at_same_q_not_an_anatomical_tendon_surface_or_bodyparts3d_surface_attachment_certificate")
                              : "hidden_until_a_source_route_centreline_inspection_is_requested")
                      << '\n';
            if (muscleDrivenState.has_value()) {
                emitPersistentInitialForceReference(*muscleDrivenState);
            }
            if (muscleDrivenState.has_value() &&
                muscleDrivenState->persistentStandTraceCaptured) {
                const auto writeTraceArray = [](const auto& values) {
                    std::cout << '[';
                    for (std::size_t valueIndex = 0u;
                         valueIndex < values.size(); ++valueIndex) {
                        if (valueIndex != 0u) std::cout << ',';
                        std::cout << values[valueIndex];
                    }
                    std::cout << ']';
                };
                std::cout << std::setprecision(17)
                          << "persistent_stand_trace={\"schema\":\"numi.human.persistent-stand-trace.v5\""
                          << ",\"driver\":\"segmented_one_step_production_horizon\""
                          << ",\"endpoint_equivalent\":\""
                          << (muscleDrivenState->persistentStandTraceEndpointBitwise
                                  ? "bitwise" : "mismatch")
                          << "\""
                          << ",\"endpoint_max_q_delta\":"
                          << muscleDrivenState->persistentStandTraceEndpointMaximumQDelta
                          << ",\"endpoint_max_v_delta\":"
                          << muscleDrivenState->persistentStandTraceEndpointMaximumVDelta
                          << ",\"work_scope\":\"production_constraint_impulse_work_by_family;exact_coordinate_projection_is_an_unowned_overwrite_not_impulse_work;muscle_virtual_work_and_static_support_reference;passive_potential_change_includes_coordinate_projection\""
                          << ",\"total_contact_normal_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintImpulseWorkJoules[0u]
                          << ",\"total_contact_tangential_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintImpulseWorkJoules[1u]
                          << ",\"total_equality_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintImpulseWorkJoules[2u]
                          << ",\"total_source_limit_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintImpulseWorkJoules[3u]
                          << ",\"total_contact_normal_absolute_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintAbsoluteImpulseWorkJoules[0u]
                          << ",\"total_contact_tangential_absolute_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintAbsoluteImpulseWorkJoules[1u]
                          << ",\"total_equality_absolute_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintAbsoluteImpulseWorkJoules[2u]
                          << ",\"total_source_limit_absolute_impulse_work_j\":"
                          << muscleDrivenState->persistentStandTraceConstraintAbsoluteImpulseWorkJoules[3u]
                          << ",\"total_muscle_virtual_work_j\":"
                          << muscleDrivenState->persistentStandTraceMuscleVirtualWorkJoules
                          << ",\"total_preload_virtual_work_j\":"
                          << muscleDrivenState->persistentStandTracePreloadVirtualWorkJoules
                          << ",\"total_support_virtual_work_j\":"
                          << muscleDrivenState->persistentStandTraceSupportVirtualWorkJoules
                          << ",\"samples\":[";
                for (std::size_t sampleIndex = 0u;
                     sampleIndex < muscleDrivenState->persistentStandTrace.size();
                     ++sampleIndex) {
                    if (sampleIndex != 0u) std::cout << ',';
                    const auto& sample =
                        muscleDrivenState->persistentStandTrace[sampleIndex];
                    std::cout << "{\"step\":" << sample.step
                              << ",\"time_seconds\":" << sample.timeSeconds
                              << ",\"kernel_maximum_acceleration\":"
                              << sample.kernelMaximumAcceleration
                              << ",\"kernel_maximum_acceleration_dof\":"
                              << sample.kernelMaximumAccelerationDof
                              << ",\"free_force_acceleration\":"
                              << sample.freeForceAcceleration
                              << ",\"free_force_acceleration_dof\":"
                              << sample.freeForceAccelerationDof
                              << ",\"constraint_velocity_delta\":"
                              << sample.constraintVelocityDelta
                              << ",\"constraint_velocity_delta_dof\":"
                              << sample.constraintVelocityDeltaDof
                              << ",\"pre_projection_velocity_delta\":"
                              << sample.preProjectionVelocityDelta
                              << ",\"pre_projection_velocity_delta_dof\":"
                              << sample.preProjectionVelocityDeltaDof
                              << ",\"published_velocity_delta\":"
                              << sample.publishedVelocityDelta
                              << ",\"published_velocity_delta_dof\":"
                              << sample.publishedVelocityDeltaDof
                              << ",\"kernel_maximum_acceleration_equality\":"
                              << sample.kernelMaximumAccelerationEquality
                              << ",\"kernel_maximum_acceleration_owner\":\""
                              << sample.kernelMaximumAccelerationOwner << "\""
                              << ",\"kernel_maximum_acceleration_equality_reference_checked\":"
                              << (sample.kernelMaximumAccelerationEqualityReferenceChecked
                                      ? "true" : "false")
                              << ",\"kernel_maximum_acceleration_equality_derivative\":"
                              << sample.kernelMaximumAccelerationEqualityDerivative
                              << ",\"kernel_maximum_acceleration_equality_position_error\":"
                              << sample.kernelMaximumAccelerationEqualityPositionError
                              << ",\"kernel_maximum_acceleration_equality_velocity_error\":"
                              << sample.kernelMaximumAccelerationEqualityVelocityError
                              << ",\"published_maximum_acceleration_dof\":"
                              << sample.publishedMaximumAccelerationDof
                              << ",\"published_maximum_acceleration\":"
                              << sample.publishedMaximumAcceleration
                              << ",\"maximum_configuration_delta_q\":"
                              << sample.maximumConfigurationDeltaQ
                              << ",\"maximum_configuration_delta\":"
                              << sample.maximumConfigurationDelta
                              << ",\"maximum_velocity_dof\":"
                              << sample.maximumVelocityDof
                              << ",\"maximum_velocity\":"
                              << sample.maximumVelocity
                              << ",\"minimum_plane_gap_m\":"
                              << sample.minimumPlaneGapMeters
                              << ",\"maximum_penetration_m\":"
                              << sample.maximumPenetrationMeters
                              << ",\"normal_impulse\":" << sample.normalImpulse
                              << ",\"maximum_normal_contact_impulse_ns\":"
                              << sample.maximumNormalContactImpulse
                              << ",\"maximum_normal_contact_impulse_index\":"
                              << sample.maximumNormalContactImpulseIndex
                              << ",\"maximum_tangential_contact_impulse_ns\":"
                              << sample.maximumTangentialContactImpulse
                              << ",\"maximum_tangential_contact_impulse_index\":"
                              << sample.maximumTangentialContactImpulseIndex
                              << ",\"maximum_source_limit_impulse_ns_or_nms\":"
                              << sample.maximumSourceLimitImpulse
                              << ",\"total_source_limit_absolute_impulse_ns_or_nms\":"
                              << sample.totalSourceLimitAbsoluteImpulse
                              << ",\"maximum_source_limit_impulse_dof\":"
                              << sample.maximumSourceLimitImpulseDof
                              << ",\"maximum_equality_impulse_index\":"
                              << sample.maximumEqualityImpulseIndex
                              << ",\"tendon_max_force_residual_n\":"
                              << sample.tendonMaximumForceResidual
                              << ",\"tendon_max_moment_residual_nm\":"
                              << sample.tendonMaximumMomentResidual
                              << ",\"maximum_equality_impulse\":"
                              << sample.maximumEqualityImpulse
                              << ",\"total_equality_impulse\":"
                              << sample.totalEqualityImpulse
                              << ",\"maximum_equality_position_projection_m_or_rad\":"
                              << sample.maximumEqualityPositionProjection
                              << ",\"total_equality_position_projection_m_or_rad\":"
                              << sample.totalEqualityPositionProjection
                              << ",\"maximum_equality_velocity_projection_m_s_or_rad_s\":"
                              << sample.maximumEqualityVelocityProjection
                              << ",\"total_equality_velocity_projection_m_s_or_rad_s\":"
                              << sample.totalEqualityVelocityProjection
                              << ",\"pre_projection_normal_contact_target_velocity_residual_m_s\":"
                              << sample.preProjectionNormalContactTargetVelocityResidual
                              << ",\"post_projection_normal_contact_target_velocity_residual_m_s\":"
                              << sample.postProjectionNormalContactTargetVelocityResidual
                              << ",\"pre_projection_source_limit_target_velocity_residual_m_s_or_rad_s\":"
                              << sample.preProjectionSourceLimitTargetVelocityResidual
                              << ",\"post_projection_source_limit_target_velocity_residual_m_s_or_rad_s\":"
                              << sample.postProjectionSourceLimitTargetVelocityResidual
                              << ",\"pre_projection_equality_target_velocity_residual_m_s_or_rad_s\":"
                              << sample.preProjectionEqualityTargetVelocityResidual
                              << ",\"post_projection_equality_target_velocity_residual_m_s_or_rad_s\":"
                              << sample.postProjectionEqualityTargetVelocityResidual
                              << ",\"contact_normal_impulse_work_j\":"
                              << sample.contactNormalImpulseWorkJoules
                              << ",\"contact_tangential_impulse_work_j\":"
                              << sample.contactTangentialImpulseWorkJoules
                              << ",\"equality_impulse_work_j\":"
                              << sample.equalityImpulseWorkJoules
                              << ",\"source_limit_impulse_work_j\":"
                              << sample.sourceLimitImpulseWorkJoules
                              << ",\"contact_normal_absolute_impulse_work_j\":"
                              << sample.contactNormalAbsoluteImpulseWorkJoules
                              << ",\"contact_tangential_absolute_impulse_work_j\":"
                              << sample.contactTangentialAbsoluteImpulseWorkJoules
                              << ",\"equality_absolute_impulse_work_j\":"
                              << sample.equalityAbsoluteImpulseWorkJoules
                              << ",\"source_limit_absolute_impulse_work_j\":"
                              << sample.sourceLimitAbsoluteImpulseWorkJoules
                              << ",\"muscle_virtual_work_j\":"
                              << sample.muscleVirtualWorkJoules
                              << ",\"passive_joint_energy_j\":" << sample.passiveJointEnergyJoules
                              << ",\"passive_joint_potential_work_j\":" << sample.passiveJointPotentialWorkJoules
                              << ",\"preload_virtual_work_j\":"
                              << sample.preloadVirtualWorkJoules
                              << ",\"support_virtual_work_j\":"
                              << sample.supportVirtualWorkJoules
                              << ",\"q\":";
                    writeTraceArray(sample.q);
                    std::cout << ",\"v\":";
                    writeTraceArray(sample.v);
                    std::cout << '}';
                }
                std::cout << "]}\n";
            }
            return 0;
        } catch (const std::exception& error) {
            std::cerr << "myosim_articulated_visual=failed error=\""
                      << error.what() << "\"\n";
            return 1;
        }
    }
